using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using Frociart;
internal class DebuggerUiTests {
 static int checks;static string output=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 static T Field<T>(object obj,string name){return(T)obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(obj);}
 static object Call(object obj,string name,params object[] args){return obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(obj,args);}
 static void Settle(){var w=System.Diagnostics.Stopwatch.StartNew();while(w.ElapsedMilliseconds<600){Application.DoEvents();System.Threading.Thread.Sleep(10);}} static void Capture(Form f,string name){Settle();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,f.Size));image.Save(Path.Combine(output,name+".png"));}}
 static void Pump(MainForm f){for(int i=0;i<500&&Field<Timer>(f,"runTimer").Enabled;i++)Call(f,"RunTick");Check(!Field<Timer>(f,"runTimer").Enabled,"Scheduled debugger command finishes or pauses");}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();
 foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);using(var d=new BreakpointDialog(new FlowNode{Breakpoint=true,BreakpointCondition="contatore >= 5"})){d.StartPosition=FormStartPosition.Manual;d.Location=new Point(-3000,-3000);d.Show();Check(d.EnabledPoint.Checked&&d.Condition.Text=="contatore >= 5","Dialog restores enabled state and condition");Capture(d,"debug-condition-"+dark);d.Condition.Text="x +";d.Apply.PerformClick();Check(d.Visible&&d.Error.Text.Length>0&&d.Condition.Text=="x +","Invalid condition stays editable");d.Condition.Text="random(5)>0";d.Apply.PerformClick();Check(d.Visible&&d.Error.Text.Contains("random"),"Random condition cannot affect runtime");d.Condition.Text="x >= 5";d.Apply.PerformClick();Check(d.DialogResult==DialogResult.OK,"Native Apply accepts valid condition");}}
 using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Show();Settle();f.EnterEditor();Settle();Field<ComboBox>(f,"speed").SelectedIndex=3;
 var d=FlowPseudocode.Decode("x=1\nx=x+1\nSTAMPA x");f.SetDocument(d,null,false);var point=d.Nodes.First(n=>n.Text=="x=x+1");f.SetBreakpoint(point,true,"x=1");Check(point.Breakpoint,"Set point changes real model");Call(f,"Undo");Check(!f.Project.Nodes.First(n=>n.Id==point.Id).Breakpoint,"Undo restores no point");Call(f,"Redo");Check(f.Project.Nodes.First(n=>n.Id==point.Id).Breakpoint,"Redo restores point");string path=Path.Combine(output,"debug-project.frociart");f.SetDocument(f.Project,path,false);Call(f,"SaveDocument",false);Check(DiagramIO.Load(path).Nodes.First(n=>n.Id==point.Id).BreakpointCondition=="x=1","Real save/reopen retains condition");
 f.StartRun();Pump(f);Check(Field<FlowDebugger>(f,"debugger").AtBreakpoint&&ValueFormatter.Format(f.Runner.Variables["x"])=="1","Run stops before operation with old variable value");Check(f.Canvas.CurrentNodeId==point.Id,"Canvas highlights unexecuted breakpoint block");Capture(f,"debug-pause");var original=f.Runner;f.SetBreakpoint(f.Project.Nodes.First(n=>n.Id==point.Id),true,"x=0");Check(Object.ReferenceEquals(original,f.Runner)&&f.Runner.Steps==2,"Editing condition preserves paused execution");f.StartRun();Pump(f);Check(f.Runner.State==RuntimeState.Completed&&f.Runner.Output.Single()=="2","Resume runs operation once");
 f.ClearBreakpoints();Check(!f.Project.Nodes.Any(n=>n.Breakpoint),"Remove all updates project");Call(f,"Undo");Check(f.Project.Nodes.Any(n=>n.Breakpoint),"Remove all can be undone");
 d=FlowPseudocode.Decode("FUNZIONE doppio(n: INTERO) -> INTERO risultato\nrisultato=n*2\nFINE FUNZIONE\nx=doppio(3)\nSTAMPA x");f.SetDocument(d,null,false);f.SingleStep();f.DebugStep(FlowDebugger.Command.Over);Pump(f);Check(f.Runner.CurrentFunctionId==null&&ValueFormatter.Format(f.Runner.Variables["x"])=="6"&&f.Runner.Output.Count==0,"Step over returns before next block");Call(f,"ResetRun",false);f.SingleStep();f.SingleStep();Check(f.Runner.CurrentFunctionName=="doppio","Step into follows function canvas");f.DebugStep(FlowDebugger.Command.Out);Pump(f);Check(f.Runner.CurrentFunctionId==null&&!f.Runner.Variables.ContainsKey("x"),"Out returns to suspended caller");f.SingleStep();Check(ValueFormatter.Format(f.Runner.Variables["x"])=="6","Next step commits caller exactly once");
 d=FlowPseudocode.Decode("LEGGI x\nx=x+1\nSTAMPA x");f.SetDocument(d,null,false);f.SingleStep();f.SingleStep();Check(f.Runner.State==RuntimeState.WaitingForInput,"Step waits for input");Field<TextBox>(f,"inputValue").Text="4";f.SubmitInput();Check(!Field<Timer>(f,"runTimer").Enabled&&ValueFormatter.Format(f.Runner.Variables["x"])=="4","Input finishes step without executing next operation");
 Field<FlowButton>(f,"debuggerButton").PerformClick();Application.DoEvents();Check(Field<FlowButton>(f,"debuggerButton").AccessibleDescription.Contains("funzioni"),"Discoverable debugger button has accessible description");var menu=Field<FlowContextMenu>(f,"debuggerMenu");Check(menu.Items.OfType<ToolStripMenuItem>().Select(item=>item.Text).SequenceEqual(new[]{"Avanti entrando nelle funzioni · F11","Avanti senza entrare · F10","Torna al chiamante · Maiusc+F11","Esegui fino al blocco selezionato · Ctrl+F10","Punto di interruzione del blocco…","Ignora i punti di interruzione","Disattiva tutti i punti di interruzione"}),"Debugger menu preserves all seven existing commands and their order");menu.Close();Settle();f.SetDocument(DiagramIO.CreateBlank(),null,false);f.EnterEditor();f.SingleStep();Field<FlowButton>(f,"debuggerButton").PerformClick();Application.DoEvents();Check(Field<FlowContextMenu>(f,"debuggerMenu").SourceControl==f,"Popup belongs to the owning window");f.Close();Check(PopupGhost.ActiveCount==0,"Closing form with debugger menu removes fade overlays");
 }
 Console.WriteLine("DEBUGGER_UI_PASS checks="+checks);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
